/*
 * levels.h -- les quinze niveaux de Relics (cinq mondes de trois), une ligne de texte par rangee de cases de
 * 20 points. GENERE par tools/relics/mklevels.py : changer le script, pas ce fichier. Inclus par main.c.
 *
 *   ' ' le ciel (le decor du fond)      '.' le mur du fond          '#' la roche      '=' la brique
 *   '-' une planche (on passe dessous)   'H' une echelle             '^' 'v' des pointes (sol, plafond)
 *   'B' un mur fissure (la dynamite)     'C' un sol qui s'effondre   '~' l'eau, les sables, la lave
 *   'D' une porte (une cle)              'i' une torche              'w' un ornement du monde
 *   't' un piege a pointes cache          'f' un jet de feu           '<' '>' un lanceur de flechettes
 *   'P' le depart   'E' la sortie   '+' un point de passage
 *   '$' un tresor   '*' la relique  'a' des balles  'd' de la dynamite  'k' une cle  '1' une vie
 *   'g' un gardien  's' un tireur   'b' une chauve-souris   'p' une araignee
 *   'o' un rocher qui roule   '!' une stalactite   'M' un pilon
 */

